<template><div class="page">
 <div class="page-header"><div><div class="page-title">责任商管管理</div><div class="page-note">按铺位维护责任商管和联系电话，分配、承接及移交均保留记录。</div></div></div>
 <div class="toolbar"><el-input v-model="query.keyword" placeholder="铺位编码、商户代码或名称" clearable @keyup.enter="search"/><el-select v-model="query.managerUserId" placeholder="责任商管" clearable filterable><el-option v-for="u in managers" :key="u.id" :label="u.displayName||u.username" :value="u.id"/></el-select><el-button type="primary" @click="search">查询</el-button></div>
 <div class="table-card"><el-table :data="rows" v-loading="loading" border>
  <el-table-column prop="stallCode" label="铺位编码" min-width="110" fixed/><el-table-column prop="floorName" label="楼层" width="90"><template #default="{row}">{{row.floorName||'-'}}</template></el-table-column>
  <el-table-column prop="merchantCode" label="商户代码" width="110"><template #default="{row}">{{row.merchantCode||'-'}}</template></el-table-column><el-table-column label="当前商户" min-width="160"><template #default="{row}">{{row.merchantName||row.stallName||'未关联商户'}}</template></el-table-column>
  <el-table-column prop="businessType" label="业态" width="110"><template #default="{row}">{{row.businessType||'-'}}</template></el-table-column><el-table-column label="责任商管" width="120"><template #default="{row}"><el-tag :type="row.managerUserId?'success':'warning'">{{row.managerName||'待分配'}}</el-tag></template></el-table-column>
  <el-table-column label="联系电话" width="130"><template #default="{row}">{{row.managerPhone||'-'}}</template></el-table-column><el-table-column label="生效时间" width="175"><template #default="{row}">{{formatDateTime(row.effectiveFrom)}}</template></el-table-column>
  <el-table-column label="操作" width="215" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openAssign(row)">{{row.managerUserId?'移交/承接':'分配'}}</el-button><el-button link @click="openQr(row)">二维码</el-button><el-button link @click="openHistory(row)">记录</el-button></template></el-table-column>
 </el-table><el-pagination class="pager" v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @change="load"/></div>
 <el-dialog v-model="assignVisible" :title="editing?.managerUserId?'移交或承接责任商户':'分配责任商管'" width="520px"><el-form label-width="100px">
  <el-form-item label="铺位商户"><el-input :model-value="`${editing?.stallCode||''} ${editing?.merchantName||editing?.stallName||''}`" disabled/></el-form-item><el-form-item v-if="editing?.managerUserId" label="变更方式"><el-radio-group v-model="form.transferType"><el-radio value="HANDOVER">移交</el-radio><el-radio value="INHERIT">承接/继承</el-radio></el-radio-group></el-form-item>
  <el-form-item label="责任商管" required><el-select v-model="form.managerUserId" filterable style="width:100%"><el-option v-for="u in managers" :key="u.id" :label="`${u.displayName||u.username}${u.phone?' · '+u.phone:''}`" :value="u.id"/></el-select></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone" maxlength="32" placeholder="留空则使用用户资料中的电话"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="255"/></el-form-item>
 </el-form><template #footer><el-button @click="assignVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
 <el-drawer v-model="historyVisible" title="责任商管变更记录" size="min(620px, 94vw)"><el-timeline><el-timeline-item v-for="h in history" :key="h.id" :timestamp="formatDateTime(h.createdAt)"><b>{{typeText(h.transferType)}}</b>：{{h.fromManagerName||'未分配'}} → {{h.toManagerName||'-'}}<div class="muted">联系电话：{{h.contactPhone||'-'}}；操作人：{{h.operatedBy||'-'}}</div><div v-if="h.remark" class="muted">备注：{{h.remark}}</div></el-timeline-item></el-timeline><el-empty v-if="!history.length" description="暂无变更记录"/></el-drawer><el-dialog v-model="qrVisible" title="铺位运营二维码" width="430px"><div class="qr-box"><b>{{qrRow?.floorName||''}} {{qrRow?.stallCode}} · {{qrRow?.merchantName||qrRow?.stallName||''}}</b><img v-if="qrUrl" :src="qrUrl"/><div class="muted">二维码永久对应本铺位，商户变更后无需重新张贴。</div></div><template #footer><el-button @click="qrVisible=false">关闭</el-button><el-button type="primary" @click="downloadQr">下载二维码</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{operationMerchantApi}from'@/api/operation';import{formatDateTime}from'@/utils/format'
const rows=ref<any[]>([]),managers=ref<any[]>([]),history=ref<any[]>([]),total=ref(0),loading=ref(false),saving=ref(false),assignVisible=ref(false),historyVisible=ref(false),editing=ref<any>(null),qrVisible=ref(false),qrUrl=ref(''),qrRow=ref<any>(null)
const query=reactive<any>({keyword:'',managerUserId:undefined,pageNum:1,pageSize:20}),form=reactive<any>({managerUserId:undefined,contactPhone:'',remark:'',transferType:'HANDOVER'})
async function load(){loading.value=true;try{const r:any=await operationMerchantApi.page(query);rows.value=r.records||[];total.value=Number(r.total)||0}finally{loading.value=false}}async function loadManagers(){managers.value=(await operationMerchantApi.managers())as any||[]}function search(){query.pageNum=1;load()}
function openAssign(row:any){editing.value=row;form.managerUserId=row.managerUserId||undefined;form.contactPhone=row.managerPhone||'';form.remark='';form.transferType='HANDOVER';assignVisible.value=true}async function save(){if(!form.managerUserId){ElMessage.warning('请选择责任商管');return}saving.value=true;try{await operationMerchantApi.assign({stallId:editing.value.stallId,...form});ElMessage.success('责任商管已保存');assignVisible.value=false;await load()}finally{saving.value=false}}async function openHistory(row:any){history.value=(await operationMerchantApi.history(row.stallId))as any||[];historyVisible.value=true}async function openQr(row:any){if(qrUrl.value)URL.revokeObjectURL(qrUrl.value);const b:any=await operationMerchantApi.qr(row.stallId);qrUrl.value=URL.createObjectURL(b);qrRow.value=row;qrVisible.value=true}function downloadQr(){const a=document.createElement('a');a.href=qrUrl.value;a.download=`${qrRow.value?.stallCode||'铺位'}-运营二维码.png`;a.click()}const typeText=(v:string)=>({ASSIGN:'首次分配',HANDOVER:'移交',INHERIT:'承接/继承'}as any)[v]||v;onMounted(async()=>{await Promise.all([load(),loadManagers()])})
</script><style scoped>.page-note{margin-top:6px;color:#909399;font-size:13px}.toolbar{display:flex;gap:10px;margin-bottom:12px}.toolbar .el-input{width:300px}.toolbar .el-select{width:180px}.pager{margin-top:12px;display:flex;justify-content:flex-end}.muted{margin-top:5px;color:#909399;font-size:13px}.qr-box{text-align:center}.qr-box img{display:block;width:min(320px,80vw);margin:12px auto}@media(max-width:768px){.toolbar{flex-wrap:wrap}.toolbar .el-input,.toolbar .el-select{width:100%}.table-card{overflow-x:auto}}</style>
